import{_ as i,l,o as e,c as s,v as t,p as n,x as r,d as C,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"掩模 CD 均匀性","description":"","frontmatter":{"title":"掩模 CD 均匀性","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/mask-cdu.md","filePath":"litho/mask-cdu.md","lastUpdated":1789023840000}'),D={name:"litho/mask-cdu.md"};function h(p,a,m,c,_,u){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="掩模-cd-均匀性" tabindex="-1">掩模 CD 均匀性 <a class="header-anchor" href="#掩模-cd-均匀性" aria-label="Permalink to &quot;掩模 CD 均匀性&quot;">​</a></h1><div class="epigraph"><p>Mask CDU 是版上同一目标宽度的空间离散；晶圆看到的是它乘 MEF，不是掩模 SEM 那张图自己。</p><footer>—— 对照 ITRS/IRDS 掩模误差预算与 MEF 放大的通称</footer></div><p><a href="/litho/write-grid-shot-count">上一课</a>把边钉在写栅上。缺口是全场、全版的 CD 并不因此变平：PEC 残差、刻蚀负载、胶厚、雾化底板都会留下指纹。本课钉 mask CDU。图形放在哪（配准），留给[下一课](/litho/mask-registration）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/mask-cd-ppe">掩模 CD 与放置</a> 已把误差写成进晶圆的语言。本课补制造侧：CDU 要拆全局均值（可被剂量整体补偿）与空间变化（场内、版内、径向、疏密）。IRDS 一类路线图把 mask CDU 列进套刻/CD 总预算；先进节点 MEF 常大于 1，版上 1 nm 可以变成晶圆上更大的一截。</p><p>缺口是<strong>空间指纹</strong>，不是再定义 MEF。把整张版平均 CD 调到规格，不等于 CDU 合格——角上与中心仍可差出窗口。</p><h3 id="疏密项与径向项要分" tabindex="-1">疏密项与径向项要分 <a class="header-anchor" href="#疏密项与径向项要分" aria-label="Permalink to &quot;疏密项与径向项要分&quot;">​</a></h3><p>疏密相关 CD 指向 PEC/MPC；径向或写场拼接指向电子光学、充电与台。混在一个 σ 里，改核或改刻蚀都会打错药。测量必须带位置与局部密度标签。</p><p><span class="marginnote">报 mask CDU 时写清：二元铬还是 EUV 吸收体、ADI 还是 AEI、测量的是线还是孔。孔的 CDU 与随机打印是另一账。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>计量：掩模 CD-SEM 或光学掩模计量，按统计抽样覆盖阵列、SRAM、逻辑密度跳变。规格常分 intra-field、intra-mask。反馈：全局偏置改剂量基准；指纹进 PEC/MPC 或写模机校正图。不能靠晶圆 OPC「吃掉」一张每片都不同的掩模指纹——OPC 假定掩模可重复。</p><p>与写入时间权衡：加密采样、加遍数、降电流，CDU 往往变好，日历变差。量产点是预算交，不是实验室最好 CDU。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>MEF（mask error enhancement factor）把掩模边误差线性（一阶）映到晶圆。低 \\(k_1\\)、助条密集区 MEF 更大，所以 CDU 规格按层类型分，不能全厂一张表。雾化底板造成缓慢 CD 斜坡，像版上 flare；扫描机光学 flare 是另一项，分析要拆。</p>',14)),(e(),n(E,null,{default:r(()=>[d(o,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20PEC%5B%22PEC%20%2F%20MPC%20%E6%AE%8B%E5%B7%AE%22%5D%20--%3E%20CDU%5B%22mask%20CDU%20%E6%8C%87%E7%BA%B9%22%5D%0A%20%20ETCH%5B%22%E6%8E%A9%E6%A8%A1%E5%88%BB%E8%9A%80%E8%B4%9F%E8%BD%BD%22%5D%20--%3E%20CDU%0A%20%20GRID%5B%22%E5%86%99%E6%A0%85%E9%87%8F%E5%8C%96%22%5D%20--%3E%20CDU%0A%20%20CDU%20--%3E%20MEF%5B%22%C3%97%20MEF%22%5D%0A%20%20MEF%20--%3E%20WCD%5B%22%E6%99%B6%E5%9C%86%20CD%20%E9%A2%84%E7%AE%97%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[C(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>CDU 不含空白片缺陷、不含 pellicle 热指纹（后者在上机后出现）。不编造某节点「mask CDU = 0.x nm」的宇宙常数——规格随层与代工厂包变，只引用路线图<strong>结构</strong>（有这项预算），不抄未公开的厂内数。</p><p>后课默认：尺寸均匀性已从写入/刻蚀收账；下一课处理位置——图形中心放错，套刻预算先被版吃掉一截。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Mask CDU 是空间变化，不是平均 CD；进晶圆时乘 MEF。</li><li>疏密项与径向/拼接项分源，才能决定改 PEC 还是改台。</li><li>OPC 吃不掉每张版不同的指纹。</li><li>出处：ITRS/IRDS 掩模误差预算结构；MEF 与 mask CDU 的产线通称。</li></ul>',5))])}const A=i(D,[["render",h]]);export{f as __pageData,A as default};
